    x-data="{
        activeTab: ['dashboard','profile','security','addresses','latest_purchase','purchase_history','vouchers'].includes(window.location.hash.slice(1)) ? window.location.hash.slice(1) : 'dashboard',
        profileFirstName: @js($user['firstName'] ?: str($user['name'])->before(' ')->toString()),
        profileLastName: @js($user['lastName'] ?: str($user['name'])->after(' ')->toString()),
        profilePhone: @js($user['phone'] ?? ''),
        profileSaved: false,
        addressToast: null,
        accountRefreshUrl: @js($accountRefreshUrl),
        couponApplyUrl: @js($couponApplyUrl),
        csrfToken: @js(csrf_token()),
        showAddressModal: false,
        showInvoiceModal: false,
        statusFilter: 'all',
        searchQuery: '',
        expandedOrderId: @js($latestOrder['id'] ?? null),
        voucherSubTab: 'eligible',
        copiedVoucher: null,
        appliedToast: null,
        twoFactorEnabled: true,
        currentPassword: '',
        newPassword: '',
        confirmPassword: '',
        showCurrentPassword: false,
        showNewPassword: false,
        showConfirmPassword: false,
        passError: null,
        passSuccess: false,
        sessions: JSON.parse(atob(@js(base64_encode(json_encode($sessions))))),
        sessionToast: null,
        reviewTarget: null,
        reviewRating: 0,
        reviewHoverRating: 0,
